<script lang="ts">
  import { onMount } from 'svelte';
  import { Clipboard, KeyRound, Plus, Share2, ShieldCheck, Users } from 'lucide-svelte';
  type Member = { id: string; name: string; role: string; createdAt?: string };
  let current = $state<Member | null>(null); let members = $state<Member[]>([]); let name = $state('Zaal'); let code = $state(''); let role = $state('ADMIN'); let inviteUrl = $state(''); let message = $state(''); let busy = $state(false);
  onMount(load);
  async function load() { const session = await fetch('/api/v1/team/session'); if (session.ok) current = (await session.json()).member; if (current) { const response = await fetch('/api/v1/team/invites'); if (response.ok) members = (await response.json()).members; } }
  async function bootstrap() { busy = true; try { const response = await fetch('/api/v1/team/bootstrap', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({ name, code }) }); const payload=await response.json(); if(!response.ok) throw new Error(payload.error); current=payload.member; code=''; await load(); } catch(error){ message=error instanceof Error?error.message:'Access failed'; } finally{busy=false;} }
  async function invite() { busy = true; try { const response=await fetch('/api/v1/team/invites',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({role})}); const payload=await response.json(); if(!response.ok) throw new Error(payload.error); inviteUrl=payload.inviteUrl; message=`One-time ${role.replace('_',' ').toLowerCase()} invite created.`; } catch(error){message=error instanceof Error?error.message:'Invite failed';} finally{busy=false;} }
</script>
<svelte:head><title>Team access | ZAOstock</title><meta name="description" content="Give ZAOstock admins and crew role-scoped access without sharing one master login." /></svelte:head>
<div class="workspace-page team-page"><section class="workspace-titlebar"><div><p class="eyebrow">TEAM ACCESS / ZAO HANDOFF</p><h1>Share the room, not the master key.</h1><p>Zaal can hand Live Command to admins, stage managers, crew leads, and marketing without exposing owner credentials.</p></div><Share2 size={56} /></section>
{#if !current}<section class="owner-access"><KeyRound size={38} /><div><p class="eyebrow">OWNER BOOTSTRAP</p><h2>Enter the private organizer code</h2><p>This is used once on each organizer device. Team members join through role-specific links.</p></div><label>Your name<input bind:value={name} /></label><label>Organizer code<input type="password" bind:value={code} /></label><button class="command-button red" onclick={bootstrap} disabled={busy}>Enter command</button></section>
{:else}<section class="team-console"><header><ShieldCheck size={24} /><div><p class="eyebrow">SIGNED IN</p><h2>{current.name} · {current.role.replace('_',' ')}</h2></div></header><div class="invite-builder"><label>Access role<select bind:value={role}><option>ADMIN</option><option>STAGE_MANAGER</option><option>CREW_LEAD</option><option>MARKETING</option></select></label><button class="command-button red" onclick={invite} disabled={busy}><Plus size={17} /> Create one-time invite</button></div>{#if inviteUrl}<div class="invite-result"><code>{inviteUrl}</code><button onclick={() => navigator.clipboard.writeText(inviteUrl)}><Clipboard size={17} /> Copy</button></div>{/if}</section>
<section class="member-list"><header><Users size={21} /><div><p class="eyebrow">ZAO TEAM</p><h2>People with access</h2></div></header>{#each members as member}<article><span>{member.name.slice(0,2).toUpperCase()}</span><div><strong>{member.name}</strong><small>{member.role.replace('_',' ')}</small></div></article>{/each}</section>{/if}
{#if message}<p class="workspace-message">{message}</p>{/if}</div>
